import threading

class ReadWriteLock:
    def __init__(self):
        self._lock = threading.Lock()
        self._readers = 0
        self._wlock = threading.Lock()
        self.write_acquisitions = 0
        self.read_acquisitions = 0

    def acquire_read(self):
        with self._lock:
            self._readers += 1
            self.read_acquisitions += 1
            if self._readers == 1:
                self._wlock.acquire()

    def release_read(self):
        with self._lock:
            self._readers -= 1
            if self._readers == 0:
                self._wlock.release()

    def acquire_write(self):
        self._wlock.acquire()
        self.write_acquisitions += 1

    def release_write(self):
        self._wlock.release()
